        List<String> out = new ArrayList<>();
        if (sc.hasNextLine()) {
            for (String t : sc.nextLine().trim().split("\\s+")) {
                if (!t.isEmpty()) {
                    out.add(t);
                }
            }
        }
        return out;
    }

