import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.Scanner;
import java.util.function.Predicate;

public class Main {
    record Subject(String code, String name, int credits) {
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        List<Subject> subjects = new ArrayList<>();
        while (sc.hasNextLine()) {
            String line = sc.nextLine().trim();
            if (!line.isEmpty()) {
                String[] p = line.split(";");
                subjects.add(new Subject(p[0].trim(), p[1].trim(), Integer.parseInt(p[2].trim())));
            }
        }
        subjects.sort(Comparator.comparing(Subject::code));
        System.out.println("sorted: " + codes(subjects));
        Predicate<Subject> isJava = s -> s.name().contains("Java");
        List<Subject> java = new ArrayList<>();
        for (Subject s : subjects) {
            if (isJava.test(s)) {
                java.add(s);
            }
        }
        System.out.println("java: " + codes(java));
        int total = subjects.stream().mapToInt(Subject::credits).sum();
        System.out.println("credits: " + total);
        Predicate<Subject> isMae = s -> s.code().startsWith("MAE");
        Predicate<Subject> twoCredits = s -> s.credits() == 2;
        subjects.removeIf(isMae.and(twoCredits.negate()));
        System.out.println("after removeIf: " + codes(subjects));
    }

    static String codes(List<Subject> list) {
        StringBuilder sb = new StringBuilder();
        for (Subject s : list) {
            sb.append(sb.length() == 0 ? "" : ", ").append(s.code()).append('(').append(s.credits()).append(')');
        }
        return "[" + sb + "]";
    }
}

#!/usr/bin/env node
// CuongThai Code Lab · PRO192 (Java OOP) — LOCAL GRADER · MÁY CHẤM CHẠY TRÊN MÁY BẠN
// Exercise / Bài: pro192-cs1-an-danh-sang-lambda — From anonymous classes to lambdas and method references — same output
//
//   node cham.mjs            compile src/ with javac, run every case, check the rules, print the score
//   node cham.mjs --show     also print your whole output for every case (Hiện toàn bộ output của bạn)
//   node cham.mjs --case 2   run only case 2 (Chỉ chạy ca 2)
//
// Needs: Node.js 18+ and a JDK (javac + java on PATH, or JAVA_HOME set). Windows: PowerShell or cmd · macOS: Terminal.
// Cần: Node.js 18+ và JDK (javac + java trong PATH, hoặc đặt JAVA_HOME). The website does NOT grade this exercise:
// when this script prints ALL CHECKS PASSED, go back to the exercise page and press "Tự đánh dấu đã giải".
// Do not edit this file — the expected outputs are inside it. Đừng sửa tệp này — output mong đợi nằm trong nó.
import { spawn, spawnSync } from 'node:child_process';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

